SELECT cs.canonical_smiles, md.chembl_id, act.standard_type, act.standard_relation, act.standard_value, act.standard_units FROM activities act JOIN assays a ON act.assay_id = a.assay_id JOIN compound_structures cs ON act.molregno = cs.molregno JOIN molecule_dictionary md ON cs.molregno = md.molregno WHERE a.chembl_id = 'CHEMBL1613918' AND act.standard_value IS NOT NULL AND act.standard_relation = '=' ORDER BY cs.canonical_smiles ASC, md.chembl_id ASC, act.standard_type ASC, act.standard_relation ASC, act.standard_value ASC, act.standard_units ASC
